INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM214VPJO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'grid_in', E'A circle in the $xy$-plane has center $(3, -1)$ and passes through the point $(3, 5)$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'The radius is the distance from the center $(3, -1)$ to the point $(3, 5)$. Since both points share the same $x$-coordinate, the distance is $|5 - (-1)| = |6| = 6$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21JZ0J5', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A student has at most $\\$47$ to spend on notebooks. Each notebook costs $\\$3$ and there is a flat shipping fee of $\\$8$. Which inequality represents the number of notebooks, $n$, the student can order?', NULL, $lyceon_json$[{"key":"A","text":"$3n + 8 \\leq 47$"},{"key":"B","text":"$3n + 8 \\geq 47$"},{"key":"C","text":"$8n + 3 \\leq 47$"},{"key":"D","text":"$3n - 8 \\leq 47$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the per-notebook cost times the number of notebooks plus the shipping fee: $3n + 8$. Since the student has at most $\\$47$, the total must be less than or equal to $47$, giving $3n + 8 \\leq 47$. The inequality $3n + 8 \\geq 47$ incorrectly reverses the direction, requiring spending at least $\\$47$. The inequality $8n + 3 \\leq 47$ swaps the cost per notebook and the shipping fee. The inequality $3n - 8 \\leq 47$ subtracts the shipping fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM220Q4EF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A machine fills bottles at a constant rate of $23$ bottles per minute. A second machine fills bottles at a constant rate of $17$ bottles per minute. If both machines start at the same time, how many minutes will it take for them to fill a combined total of $600$ bottles?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$15$"},{"key":"C","text":"$26$"},{"key":"D","text":"$35$"}]$lyceon_json$::jsonb, 'B', NULL, E'The combined rate of both machines is $23 + 17 = 40$ bottles per minute. To fill $600$ bottles at $40$ bottles per minute requires $\\frac{600}{40} = 15$ minutes. The value $12$ results from a computational error when dividing. The value $26$ comes from dividing $600$ by only the first machine''s rate of $23$, ignoring the second machine. The value $35$ arises from dividing $600$ by $17$, using only the second machine''s rate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM227EXGC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What are all the solutions of $x^2 + 2x - 35 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 5$ and $x = -7$"},{"key":"B","text":"$x = -5$ and $x = 7$"},{"key":"C","text":"$x = 5$ and $x = 7$"},{"key":"D","text":"$x = -5$ and $x = -7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The equation factors as $(x + 7)(x - 5) = 0$, giving $x = -7$ and $x = 5$. The pair $x = -5$ and $x = 7$ reverses both signs from the correct factorization. The pair $x = 5$ and $x = 7$ incorrectly treats both factors as producing positive roots. The pair $x = -5$ and $x = -7$ makes both roots negative by misapplying the signs.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22YHIX2', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 + 11x + 28}{x + 4}$ for $x \\neq -4$?', NULL, $lyceon_json$[{"key":"A","text":"$x + 4$"},{"key":"B","text":"$x + 7$"},{"key":"C","text":"$x + 14$"},{"key":"D","text":"$x + 24$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $x + 7$. Factor the numerator: find two numbers that multiply to $28$ and add to $11$. Since $4 \\times 7 = 28$ and $4 + 7 = 11$, the numerator factors as $x^2 + 11x + 28 = (x + 4)(x + 7)$. Dividing by $(x + 4)$ cancels the common factor, leaving $x + 7$. The result $x + 4$ comes from keeping the factor that cancels rather than the remaining factor after division. The result $x + 14$ comes from dividing the constant term $28$ by $2$ instead of properly factoring the quadratic, yielding $14$ in place of $7$. The result $x + 24$ comes from subtracting $4$ from $28$ to get $24$ instead of finding the correct factor pair whose product is $28$ and sum is $11$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM238O4NM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'What is the radius of the circle defined by the equation $x^2 + y^2 + 10x - 4y - 7 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$36$"},{"key":"B","text":"$\\sqrt{7}$"},{"key":"C","text":"$6$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewrite the equation by completing the square. Group terms: $(x^2 + 10x) + (y^2 - 4y) = 7$. Complete the square for $x$: $x^2 + 10x + 25 = (x + 5)^2$. Complete the square for $y$: $y^2 - 4y + 4 = (y - 2)^2$. Adding $25$ and $4$ to both sides gives $(x + 5)^2 + (y - 2)^2 = 7 + 25 + 4 = 36$. Thus $r^2 = 36$ and $r = 6$. The value $36$ is $r^2$, not $r$, resulting from forgetting to take the square root. The value $\\sqrt{7}$ comes from using the constant term $7$ directly as $r^2$ without completing the square. The value $3$ arises from an arithmetic error in completing the square, such as computing $\\sqrt{9}$ instead of $\\sqrt{36}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23FH3U4', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'The equation $kx + 5y = 60$ represents a line that passes through the point $(3, 6)$. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-10$"},{"key":"B","text":"$6$"},{"key":"C","text":"$10$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $10$. Substitute the point $(3, 6)$ into $kx + 5y = 60$: $k(3) + 5(6) = 60$, which gives $3k + 30 = 60$. Subtracting $30$ from both sides yields $3k = 30$, and dividing by $3$ gives $k = 10$. The value $30$ results from stopping at the intermediate step $3k = 30$ without dividing by $3$. The value $-10$ comes from a sign error when dividing $30$ by $3$, yielding $-10$ instead of $10$. The value $6$ results from dividing $30$ by $5$ (the coefficient of $y$) instead of by $3$ (the coefficient of $k$ after substitution), giving $\\frac{30}{5} = 6$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23L5NNB', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $(4x + 11)(4x - 11)$?', NULL, $lyceon_json$[{"key":"A","text":"$4x^2 - 121$"},{"key":"B","text":"$8x^2 - 121$"},{"key":"C","text":"$16x^2 - 121$"},{"key":"D","text":"$16x^2 + 121$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $16x^2 - 121$. This expression is a difference of squares: $(a + b)(a - b) = a^2 - b^2$. Here $a = 4x$ and $b = 11$, so $(4x)^2 - 11^2 = 16x^2 - 121$. The result $4x^2 - 121$ incorrectly computes $(4x)^2$ as $4x^2$, squaring only the variable and not the coefficient. The result $8x^2 - 121$ confuses squaring with doubling, computing $2 \\cdot 4x^2 = 8x^2$ instead of $(4x)^2 = 16x^2$. The result $16x^2 + 121$ uses a sum of squares instead of a difference, ignoring the opposite signs in the factors.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM249RMGA', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $9x - 37 = 44$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{9}$"},{"key":"B","text":"$-9$"},{"key":"C","text":"$9$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $9$. Add $37$ to both sides of $9x - 37 = 44$ to get $9x = 81$, then divide both sides by $9$ to get $x = 9$. The value $\\frac{7}{9}$ results from subtracting $37$ from $44$ instead of adding, then dividing by $9$. The value $-9$ comes from a sign error when dividing $81$ by $9$. The value $81$ is the result of the intermediate step $9x = 81$ without completing the final division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24P5L9W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato yield. She selects $60$ tomato plants and randomly assigns $30$ to receive the new fertilizer and $30$ to receive no fertilizer. After $8$ weeks, she measures the total weight of tomatoes produced by each plant. Which of the following best describes this study?', NULL, $lyceon_json$[{"key":"A","text":"This is an observational study because the researcher observed the plants over time."},{"key":"B","text":"This is a randomized experiment, so a causal conclusion about the fertilizer's effect is supported if a significant difference is found."},{"key":"C","text":"This is a survey because the researcher collected data from the plants."},{"key":"D","text":"This is an observational study, so only an association between the fertilizer and yield can be established."}]$lyceon_json$::jsonb, 'B', NULL, E'The researcher imposed a treatment (the new fertilizer) and randomly assigned plants to treatment and control groups, which defines this as a randomized experiment. Random assignment balances confounding variables across groups, so a statistically significant difference in yield can support a causal conclusion about the fertilizer''s effect. The claim that this is an observational study because the researcher observed the plants incorrectly defines an observational study by the act of watching subjects over time; an observational study is one in which the researcher does not impose a treatment or randomly assign subjects to groups. The claim that this is a survey confuses a controlled experiment with a survey, which collects self-reported data from respondents rather than measuring experimental outcomes. The claim that this is an observational study permitting only an association applies the limitation of observational studies to this experiment; in an observational study, the researcher has no control over treatment assignment, so confounding variables cannot be ruled out and only an association — not a causal relationship — can be established. Here, random assignment was used, so this limitation does not apply.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM260FV27', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town''s population was $8{,}200$ in 2018 and $9{,}676$ in 2020. If the population increased by the same percent each year, what was the approximate annual percent increase?', NULL, $lyceon_json$[{"key":"A","text":"$7\\%$"},{"key":"B","text":"$8.6\\%$"},{"key":"C","text":"$9\\%$"},{"key":"D","text":"$18\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $r$ be the annual percent increase. After two years of compound growth, the population satisfies $8{,}200(1 + r)^2 = 9{,}676$. Dividing both sides by $8{,}200$ gives $(1 + r)^2 = \\frac{9{,}676}{8{,}200} = 1.18$. Taking the square root yields $1 + r \\approx 1.0863$, so $r \\approx 0.0863$ or approximately $8.6\\%$. The value $9\\%$ comes from computing the total two-year increase as $\\frac{9{,}676 - 8{,}200}{8{,}200} = 18\\%$ and dividing by $2$, which treats the growth as simple (linear) rather than compound; the correct setup uses $(1 + r)^2 = 1.18$, not $1 + 2r = 1.18$. The value $7\\%$ results from an arithmetic slip during the division or square root step. The value $18\\%$ is the total percent change over the entire two-year period, not the annual rate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26NHX8T', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $5x - 2y = 14$. Line $q$ is perpendicular to line $p$ and passes through the point $(10, -3)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$1$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $1$. Rewrite line $p$ in slope-intercept form: $5x - 2y = 14$ becomes $y = \\frac{5}{2}x - 7$, so the slope of line $p$ is $\\frac{5}{2}$. The perpendicular slope is $-\\frac{2}{5}$. Using point-slope form with $(10, -3)$: $y + 3 = -\\frac{2}{5}(x - 10)$, which gives $y + 3 = -\\frac{2}{5}x + 4$, so $y = -\\frac{2}{5}x + 1$. The $y$-intercept is $1$. The value $-7$ comes from finding the $y$-intercept of line $p$ instead of line $q$. The value $-1$ results from a sign error in the point-slope computation. The value $7$ comes from using the $y$-intercept of line $p$ with the wrong sign.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26XTTBD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In right triangle $PQR$, angle $R$ is the right angle. If $\\sin(P) = \\frac{5}{13}$, what is $\\cos(P)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{13}$"},{"key":"B","text":"$\\frac{12}{13}$"},{"key":"C","text":"$\\frac{5}{12}$"},{"key":"D","text":"$\\frac{13}{12}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $\\sin(P) = \\frac{5}{13}$, the ratio of the side opposite angle $P$ to the hypotenuse is $5:13$. By the Pythagorean identity, $\\cos^2(P) = 1 - \\sin^2(P) = 1 - \\frac{25}{169} = \\frac{144}{169}$, so $\\cos(P) = \\frac{12}{13}$. The sides are proportional to $5:12:13$, and the actual lengths need not be known — only the ratios matter. The answer $\\frac{5}{13}$ confuses sine with cosine, reusing the given ratio for the wrong function. The answer $\\frac{5}{12}$ gives the tangent ratio (opposite to adjacent) instead of cosine (adjacent to hypotenuse). The answer $\\frac{13}{12}$ inverts the correct cosine ratio, placing the hypotenuse over the adjacent side.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27CGHX8', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $\\frac{39n^8}{13n^3}$?', NULL, $lyceon_json$[{"key":"A","text":"$3n^5$"},{"key":"B","text":"$3n^{11}$"},{"key":"C","text":"$13n^5$"},{"key":"D","text":"$39n^5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $3n^5$. To simplify $\\frac{39n^8}{13n^3}$, divide the coefficients: $\\frac{39}{13} = 3$, and subtract the exponents: $n^{8-3} = n^5$. The result $3n^{11}$ comes from adding the exponents ($8 + 3 = 11$) instead of subtracting them, which is the rule for multiplication, not division. The result $13n^5$ comes from subtracting the coefficients ($39 - 13 = 26$... actually dividing incorrectly as $\\frac{39}{3} = 13$) rather than dividing $39 \\div 13 = 3$. The result $39n^5$ comes from handling the exponents correctly but neglecting to divide the coefficients entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27MQ9GI', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $3(2x + 7) - 4x = 51$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$-15$"},{"key":"B","text":"$3$"},{"key":"C","text":"$15$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $15$. Distribute to get $6x + 21 - 4x = 51$. Combine like terms: $2x + 21 = 51$. Subtract $21$ from both sides: $2x = 30$. Divide by $2$: $x = 15$. The value $3$ results from incorrectly adding $6x$ and $4x$ to get $10x + 21 = 51$, yielding $10x = 30$ and $x = 3$. The value $30$ comes from stopping at $2x = 30$ without dividing by $2$. The value $-15$ is a sign error on the final result.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27W8CY4', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'If $x + y = 19$ and $x - y = 5$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$12$"},{"key":"C","text":"$24$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations eliminates $y$: $(x + y) + (x - y) = 19 + 5$, which gives $2x = 24$, so $x = 12$. The value $7$ is the value of $y$, not $x$. The value $24$ is the result of $2x = 24$ without completing the final division by $2$. The value $10$ results from an arithmetic error in the addition step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM286JLET', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What are all values of $x$ that satisfy the inequality $3x - 7 > 14$?', NULL, $lyceon_json$[{"key":"A","text":"$x > 3$"},{"key":"B","text":"$x > 7$"},{"key":"C","text":"$x < 7$"},{"key":"D","text":"$x > 21$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding $7$ to both sides of $3x - 7 > 14$ gives $3x > 21$. Dividing both sides by $3$ yields $x > 7$. The value $x > 21$ results from stopping after the first step and not dividing by $3$. The value $x > 3$ comes from dividing $21$ by $7$ instead of by $3$. The value $x < 7$ reverses the inequality direction, which is incorrect since both sides were divided by a positive number.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28TKY30', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $f$ satisfies $f(3) = 22$ and $f(11) = 54$. What is the value of $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$-10$"},{"key":"B","text":"$4$"},{"key":"C","text":"$10$"},{"key":"D","text":"$34$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $10$. First find the slope: $m = \\frac{54 - 22}{11 - 3} = \\frac{32}{8} = 4$. Using $f(3) = 22$: $4(3) + b = 22$, so $12 + b = 22$ and $b = 10$. Therefore $f(x) = 4x + 10$, and $f(0) = 10$. The value $4$ comes from finding the slope but reporting it as $f(0)$ instead of computing the $y$-intercept. The value $34$ results from an arithmetic error such as computing $f(0) = 22 + 4(3) = 34$ instead of $22 - 4(3) = 10$. The value $-10$ is a sign error on the correct $y$-intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29WM7WQ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'Which of the following points is in the solution set of the system of inequalities $2x - 5y < 11$ and $x + 3y \\geq 4$?', NULL, $lyceon_json$[{"key":"A","text":"$(3, -1)$"},{"key":"B","text":"$(0, 0)$"},{"key":"C","text":"$(7, 1)$"},{"key":"D","text":"$(1, -2)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $(7, 1)$ into both inequalities: $2(7) - 5(1) = 9 < 11$ is true, and $7 + 3(1) = 10 \\geq 4$ is true, so $(7, 1)$ satisfies both. For $(3, -1)$: $2(3) - 5(-1) = 11$, which is not strictly less than $11$, so it fails the first inequality. For $(0, 0)$: $0 + 0 = 0$, which is not greater than or equal to $4$, so it fails the second inequality. For $(1, -2)$: $2(1) - 5(-2) = 12$, which is not less than $11$, so it fails the first inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A8NE8G', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g(x) = (x - 5)^2 + 3$ has a minimum value. What is that minimum value?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'A', NULL, E'In vertex form $g(x) = (x - 5)^2 + 3$, the minimum value of $(x - 5)^2$ is $0$, occurring when $x = 5$. Therefore the minimum value of $g$ is $0 + 3 = 3$. The value $5$ confuses the $x$-coordinate of the vertex with the minimum output. The value $-3$ applies a sign error to the constant. The value $28$ evaluates $g(0) = 25 + 3$ instead of finding the vertex.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ANQR1Z', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $7x - 3y = 21$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $-7$. To find the $y$-intercept, set $x = 0$ in the equation: $7(0) - 3y = 21$, which gives $-3y = 21$, so $y = -7$. The value $7$ results from a sign error when dividing $21$ by $-3$. The value $3$ comes from confusing the coefficient of $y$ in the equation with the intercept. The value $-3$ results from misidentifying the coefficient as the intercept value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AYZN8V', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'For $x \\neq 0$, $y \\neq 0$, and $x \\neq -y$, which of the following is equivalent to $\\frac{x^{-2} - y^{-2}}{x^{-1} + y^{-1}}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{xy}$"},{"key":"B","text":"$\\frac{x - y}{xy}$"},{"key":"C","text":"$\\frac{y - x}{xy}$"},{"key":"D","text":"$\\frac{y - x}{x^2y^2}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $\\frac{y - x}{xy}$. Rewrite the expression using common denominators: $\\frac{\\frac{1}{x^2} - \\frac{1}{y^2}}{\\frac{1}{x} + \\frac{1}{y}} = \\frac{\\frac{y^2 - x^2}{x^2y^2}}{\\frac{y + x}{xy}}$. Factor the numerator as a difference of squares: $y^2 - x^2 = (y - x)(y + x)$. Then divide by multiplying by the reciprocal: $\\frac{(y - x)(y + x)}{x^2y^2} \\cdot \\frac{xy}{y + x} = \\frac{y - x}{xy}$. The result $\\frac{1}{xy}$ loses the $(y - x)$ factor during cancellation, treating $y^2 - x^2$ as if it were $(y + x)^2$ or simply $1$ after cancellation. The result $\\frac{x - y}{xy}$ reverses the sign in the numerator, factoring $y^2 - x^2$ as $(x - y)(x + y)$ instead of $(y - x)(y + x)$, which flips the sign. The result $\\frac{y - x}{x^2y^2}$ correctly factors the numerator but fails to multiply by the reciprocal of the denominator, leaving $x^2y^2$ in the denominator instead of simplifying to $xy$.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CK6THX', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ if $\\frac{5(x - 3)}{2} = 35$?', NULL, $lyceon_json$[{"key":"A","text":"$-17$"},{"key":"B","text":"$11$"},{"key":"C","text":"$14$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $17$. Multiply both sides by $2$ to get $5(x - 3) = 70$. Divide both sides by $5$ to get $x - 3 = 14$. Add $3$ to both sides to get $x = 17$. The value $14$ results from stopping at the intermediate step $x - 3 = 14$ without adding $3$. The value $11$ comes from subtracting $3$ from $14$ instead of adding it. The value $-17$ is a sign error applied to the correct magnitude.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DA7QFU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A linear model estimates that $y = 3.7x + 14.2$. For a data point where $x = 9$, the actual $y$-value is $42$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$-5.5$"},{"key":"B","text":"$5.5$"},{"key":"C","text":"$-47.5$"},{"key":"D","text":"$47.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value when $x = 9$ is $3.7(9) + 14.2 = 33.3 + 14.2 = 47.5$. The residual is the actual value minus the predicted value: $42 - 47.5 = -5.5$. The value $5.5$ results from reversing the subtraction order (predicted minus actual) instead of actual minus predicted. The value $-47.5$ comes from subtracting the predicted value from zero rather than the actual value. The value $47.5$ is simply the predicted value itself, not the residual.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FX7T23', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $\\$145$ is on sale for $\\$101.50$. What is the percent discount on the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$25\\%$"},{"key":"B","text":"$30\\%$"},{"key":"C","text":"$43.50\\%$"},{"key":"D","text":"$70\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount amount is $\\$145 - \\$101.50 = \\$43.50$. The percent discount is $\\frac{43.50}{145} \\times 100 = 30\\%$. The value $25\\%$ results from an arithmetic error in the division. The value $43.50\\%$ comes from treating the dollar discount as though it were already a percentage. The value $70\\%$ represents the portion of the price that is paid, not the discount.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G2WYKN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'As $x$ increases without bound, which of the following expressions also increases without bound?', NULL, $lyceon_json$[{"key":"A","text":"$-3x^2 + 5x$"},{"key":"B","text":"$7 - x^3$"},{"key":"C","text":"$2x^3 + x$"},{"key":"D","text":"$4x^2 - x^3$"}]$lyceon_json$::jsonb, 'C', NULL, E'The end behavior of a polynomial is determined by its leading term. For $2x^3 + x$, the leading term $2x^3$ has a positive coefficient and odd degree, so it increases without bound as $x$ increases. The expression $-3x^2 + 5x$ has a negative leading coefficient, so it decreases without bound. The expression $7 - x^3$ has a leading term of $-x^3$, which also decreases without bound. The expression $4x^2 - x^3$ has a leading term of $-x^3$, so despite the $4x^2$ term, it ultimately decreases without bound.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GI39US', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The graphs of $y = x^2 - 4x + 3$ and $y = x - 1$ intersect at two points. What is the sum of the $y$-coordinates of these intersection points?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$4$"},{"key":"D","text":"$-1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x^2 - 4x + 3 = x - 1$ gives $x^2 - 5x + 4 = 0$, which factors as $(x - 1)(x - 4) = 0$. At $x = 1$, $y = 1 - 1 = 0$. At $x = 4$, $y = 4 - 1 = 3$. The sum of the $y$-coordinates is $0 + 3 = 3$. The value $5$ is the sum of the $x$-coordinates, not the $y$-coordinates. The value $4$ uses only the larger $x$-coordinate without computing the corresponding $y$-value sum. The value $-1$ results from subtracting the $y$-coordinates instead of adding them.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GVVAVD', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $2x^2 - 7x + 9 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = (-7)^2 - 4(2)(9) = 49 - 72 = -23$. Since the discriminant is negative, the equation has $0$ real solutions. The answer $1$ would require a discriminant of exactly zero, producing a single repeated root, but $-23 \\neq 0$. The answer $2$ would require a positive discriminant, but $-23 < 0$. The answer $3$ confuses the number of terms in the equation (three: $2x^2$, $-7x$, and $9$) with the number of solutions; a quadratic equation has at most $2$ real solutions regardless of the number of terms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H47VY0', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'For what value of $k$ does the following system of equations have no solution? $$kx + 3y = 14$$ $$8x + 6y = 9$$', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$8$"},{"key":"C","text":"$3$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'D', NULL, E'A system has no solution when the lines are parallel but not identical, which occurs when $\\frac{k}{8} = \\frac{3}{6}$ but $\\frac{14}{9} \\neq \\frac{3}{6}$. Since $\\frac{3}{6} = \\frac{1}{2}$, setting $\\frac{k}{8} = \\frac{1}{2}$ gives $k = 4$. Checking: $\\frac{14}{9} \\neq \\frac{1}{2}$, so the lines are parallel and distinct, confirming no solution. The value $-4$ applies a sign error in the proportionality calculation. The value $8$ incorrectly assumes the $x$-coefficients must be equal rather than proportional. The value $3$ is the $y$-coefficient from the first equation and does not result from the parallel-line condition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H7YYRV', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A function is defined by $f(x) = 7x - 23$. What is the value of $f(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$-12$"},{"key":"B","text":"$2$"},{"key":"C","text":"$12$"},{"key":"D","text":"$58$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $12$. Substitute $x = 5$: $f(5) = 7(5) - 23 = 35 - 23 = 12$. The value $-12$ results from a sign error, computing $23 - 35$ instead of $35 - 23$. The value $2$ comes from an equation setup error such as using $5 \\cdot 5 - 23 = 2$. The value $58$ results from adding $23$ to $35$ instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I9HS0B', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ in the solution to the system of equations below? $$5x - 3y = 16$$ $$2x + 3y = 19$$', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding the two equations eliminates $y$: $(5x - 3y) + (2x + 3y) = 16 + 19$, giving $7x = 35$, so $x = 5$. The value $3$ is the value of $y$, not $x$, since substituting $x = 5$ into $2(5) + 3y = 19$ gives $y = 3$. The value $-5$ results from a sign error when dividing $35$ by $7$. The value $7$ comes from dividing $35$ by $5$ instead of by $7$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J07UNI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The functions $f(x) = x^3 - 9x$ and $g(x) = x^2 - 2x - 3$ are defined for all real numbers. For what value of $x$ is $\\frac{f(x)}{g(x)}$ undefined while $f(x) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$0$"},{"key":"D","text":"$-1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring gives $f(x) = x(x - 3)(x + 3)$ and $g(x) = (x - 3)(x + 1)$. The fraction is undefined where $g(x) = 0$, which occurs at $x = 3$ and $x = -1$. Checking $f(x) = 0$: $f(3) = 3(0)(6) = 0$ and $f(-1) = (-1)(-4)(2) = 8 \\neq 0$. So $x = 3$ is the only value where both conditions hold. The value $-3$ makes $f(x) = 0$ but $g(-3) = 9 + 6 - 3 = 12 \\neq 0$, so the fraction is defined there. The value $0$ makes $f(x) = 0$ but $g(0) = -3 \\neq 0$. The value $-1$ makes $g(x) = 0$ but $f(-1) = 8 \\neq 0$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K8NJC5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the sum of the solutions of $x^2 - 13x + 42 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$42$"},{"key":"C","text":"$7$"},{"key":"D","text":"$-13$"}]$lyceon_json$::jsonb, 'A', NULL, E'The equation $x^2 - 13x + 42 = 0$ factors as $(x - 6)(x - 7) = 0$, giving solutions $x = 6$ and $x = 7$. Their sum is $6 + 7 = 13$. The value $42$ confuses the sum with the product of the roots. The value $7$ is only one of the two solutions, not their sum. The value $-13$ results from a sign error when applying Vieta''s formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KEI5BW', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = mx - 8$, and $h(5) = 27$. What is the value of $m$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$\\frac{19}{5}$"},{"key":"C","text":"$7$"},{"key":"D","text":"$35$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $7$. Substitute $x = 5$ and $h(5) = 27$ into $h(x) = mx - 8$: $5m - 8 = 27$. Add $8$ to both sides: $5m = 35$. Divide by $5$: $m = 7$. The value $\\frac{19}{5}$ results from subtracting $8$ from $27$ to get $19$ instead of adding $8$, then dividing by $5$. The value $35$ comes from stopping at $5m = 35$ without completing the division. The value $-7$ is a sign error on the correct answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KM9QQJ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $(2x^2 - 5x + 3)(x + 7)$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^3 + 9x^2 - 32x + 21$"},{"key":"B","text":"$2x^3 + 9x^2 - 38x + 21$"},{"key":"C","text":"$2x^3 + 9x^2 - 32x - 21$"},{"key":"D","text":"$2x^3 + 19x^2 - 32x + 21$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $2x^3 + 9x^2 - 32x + 21$. Distribute each term of $(2x^2 - 5x + 3)$ across $(x + 7)$: $2x^2 \\cdot x + 2x^2 \\cdot 7 - 5x \\cdot x - 5x \\cdot 7 + 3 \\cdot x + 3 \\cdot 7 = 2x^3 + 14x^2 - 5x^2 - 35x + 3x + 21$. Combining like terms gives $2x^3 + 9x^2 - 32x + 21$. The result with $-38x$ incorrectly computes $-35x - 3x = -38x$ instead of $-35x + 3x = -32x$, applying a sign error on the $+3x$ term. The result with $-21$ incorrectly assigns a negative sign to $3 \\times 7$, producing $-21$ instead of $+21$. The result with $19x^2$ adds $14x^2 + 5x^2 = 19x^2$ instead of correctly subtracting $14x^2 - 5x^2 = 9x^2$, dropping the negative on $-5x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L2IVMG', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'If $x + y = 7$ and $x^2 + y^2 = 25$, what is the value of $xy$?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$7$"},{"key":"C","text":"$25$"},{"key":"D","text":"$-12$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $(x + y)^2 = x^2 + 2xy + y^2$, substituting gives $7^2 = 25 + 2xy$, so $49 = 25 + 2xy$ and $2xy = 24$, meaning $xy = 12$. The value $7$ simply restates the sum $x + y$ without further computation. The value $25$ restates $x^2 + y^2$ without using the identity. The value $-12$ applies an incorrect sign when isolating $xy$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L4LMO7', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sold $173$ tickets for a show. Adult tickets cost $\\$14$ each and child tickets cost $\\$9$ each. If the total ticket revenue was $\\$1{,}937$, how many adult tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$80$"},{"key":"B","text":"$97$"},{"key":"C","text":"$76$"},{"key":"D","text":"$38$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $a$ be the number of adult tickets and $c$ the number of child tickets. The system is $a + c = 173$ and $14a + 9c = 1937$. Substituting $c = 173 - a$ into the revenue equation gives $14a + 9(173 - a) = 1937$, which simplifies to $14a + 1557 - 9a = 1937$, then $5a = 380$, so $a = 76$. The value $97$ is the number of child tickets, not adult tickets. The value $80$ results from an arithmetic error when computing $\\frac{380}{5}$. The value $38$ comes from stopping at $5a = 380$ and dividing by $10$ instead of $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LUDQMD', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'If $5x^2 = 125$, what is the positive value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$25$"},{"key":"B","text":"$5$"},{"key":"C","text":"$\\sqrt{125}$"},{"key":"D","text":"$625$"}]$lyceon_json$::jsonb, 'B', NULL, E'Dividing both sides by $5$ gives $x^2 = 25$, so $x = 5$ (taking the positive root). The value $25$ comes from dividing $125$ by $5$ but forgetting to take the square root. The value $\\sqrt{125}$ results from taking the square root of $125$ without first dividing by $5$. The value $625$ comes from squaring $25$ instead of taking its square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M4ZPR6', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $3x^2 + 18x + 31$?', NULL, $lyceon_json$[{"key":"A","text":"$3(x + 3)^2 + 4$"},{"key":"B","text":"$3(x + 3)^2 + 22$"},{"key":"C","text":"$3(x + 3)^2 + 31$"},{"key":"D","text":"$3(x + 6)^2 - 77$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $3(x + 3)^2 + 4$. To complete the square, factor out $3$ from the first two terms: $3(x^2 + 6x) + 31$. Inside the parentheses, add and subtract $(\\frac{6}{2})^2 = 9$: $3(x^2 + 6x + 9 - 9) + 31 = 3(x + 3)^2 - 27 + 31 = 3(x + 3)^2 + 4$. The result $3(x + 3)^2 + 22$ subtracts only $9$ from $31$ instead of $3 \\times 9 = 27$, forgetting to distribute the factor of $3$. The result $3(x + 3)^2 + 31$ completes the square inside the parentheses but omits the compensating subtraction of $27$ entirely. The result $3(x + 6)^2 - 77$ fails to halve the coefficient of $x$ before squaring, using $6$ instead of $3$, and then compensates incorrectly: $3(36) = 108$, so $31 - 108 = -77$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MBGRG3', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A phone plan charges $\\$37$ per month plus $\\$0.06$ per text message. A second plan charges $\\$22$ per month plus $\\$0.11$ per text message. For what numbers of text messages $t$ is the first plan strictly less expensive than the second plan?', NULL, $lyceon_json$[{"key":"A","text":"$t < 300$"},{"key":"B","text":"$t > 150$"},{"key":"C","text":"$t < 150$"},{"key":"D","text":"$t > 300$"}]$lyceon_json$::jsonb, 'D', NULL, E'Setting the cost of the first plan less than the second: $37 + 0.06t < 22 + 0.11t$. Subtracting $0.06t$ from both sides gives $37 < 22 + 0.05t$. Subtracting $22$ gives $15 < 0.05t$. Dividing by $0.05$ yields $300 < t$, or equivalently $t > 300$. The result $t < 300$ comes from flipping the inequality when dividing by a positive number. The result $t > 150$ comes from dividing $15$ by $0.10$ instead of $0.05$. The result $t < 150$ combines both of those errors.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MGKBVT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $\\frac{7}{4}$ cups of rice to serve $11$ people. How many cups of rice are needed to serve $44$ people?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$\\frac{77}{4}$"},{"key":"D","text":"$\\frac{49}{4}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since the recipe serves $11$ people and the goal is to serve $44$ people, the scaling factor is $\\frac{44}{11} = 4$. Multiplying $\\frac{7}{4}$ cups by $4$ gives $\\frac{7}{4} \\times 4 = 7$ cups. The value $5$ results from an arithmetic error in the multiplication. The value $\\frac{77}{4}$ comes from incorrectly multiplying $\\frac{7}{4}$ by $11$ instead of the scaling factor $4$. The value $\\frac{49}{4}$ results from multiplying $\\frac{7}{4}$ by $7$ (the numerator) rather than by the correct scaling factor $4$, giving $\\frac{7 \\times 7}{4} = \\frac{49}{4}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NZNXPY', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ in the equation $\\frac{3x + 1}{4} + \\frac{x - 5}{2} = 9$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$5$"},{"key":"C","text":"$9$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $9$. Multiply every term by $4$ to clear denominators: $(3x + 1) + 2(x - 5) = 36$. Distribute: $3x + 1 + 2x - 10 = 36$. Combine like terms: $5x - 9 = 36$. Add $9$: $5x = 45$. Divide by $5$: $x = 9$. The value $10$ results from failing to multiply the second fraction by $2$ when clearing denominators, giving $4x - 4 = 36$ and $x = 10$. The value $5$ comes from a sign error during distribution, writing $2x + 10$ instead of $2x - 10$, which leads to $5x + 11 = 36$ and $x = 5$. The value $-9$ applies the wrong sign to the correct magnitude.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O7A2RI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, the hypotenuse has length $19$ and one of the acute angles measures $34^\\circ$. What is the length of the side opposite the $34^\\circ$ angle, to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$10.6$"},{"key":"B","text":"$15.8$"},{"key":"C","text":"$12.8$"},{"key":"D","text":"$34.0$"}]$lyceon_json$::jsonb, 'A', NULL, E'The side opposite the $34^\\circ$ angle is found using sine: $\\text{opposite} = 19 \\sin(34^\\circ) \\approx 19 \\times 0.5592 \\approx 10.6$. The value $15.8$ results from using cosine instead of sine: $19 \\cos(34^\\circ) \\approx 19 \\times 0.8290 \\approx 15.8$, which gives the adjacent side, not the opposite side. The value $12.8$ comes from incorrectly using tangent: $19 \\tan(34^\\circ) \\approx 19 \\times 0.6745 \\approx 12.8$, but tangent relates opposite to adjacent, not opposite to hypotenuse. The value $34.0$ results from dividing the hypotenuse by sine ($\\frac{19}{\\sin 34^\\circ} \\approx 34.0$) instead of multiplying, which inverts the relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OST6C4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'If $f(x) = x^2 - 9x + 14$, what is $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-14$"},{"key":"D","text":"$32$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 3$ gives $f(3) = (3)^2 - 9(3) + 14 = 9 - 27 + 14 = -4$. The value $4$ results from a sign error, treating $9 - 27$ as $18$ instead of $-18$. The value $-14$ comes from miscalculating $9 - 27 + 14$ as $9 - 23$. The value $32$ comes from incorrectly computing $9 + 9 + 14$ by adding all terms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PPDRX2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $131^\\circ$. If angle $P$ measures $54^\\circ$, what is the measure, in degrees, of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$49^\\circ$"},{"key":"B","text":"$77^\\circ$"},{"key":"C","text":"$54^\\circ$"},{"key":"D","text":"$103^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Thus $131^\\circ = 54^\\circ + \\text{angle } Q$, so angle $Q = 131^\\circ - 54^\\circ = 77^\\circ$. The value $49^\\circ$ comes from subtracting $131^\\circ$ from $180^\\circ$, which gives the interior angle at $R$ rather than at $Q$. The value $54^\\circ$ is the measure of angle $P$ itself, not angle $Q$. The value $103^\\circ$ results from computing $180^\\circ - 77^\\circ$, which is the supplement of the correct answer rather than the answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PTQSGK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set consists of the values $13, 17, 19, 22, 22, 25, 31$. If the value $31$ is replaced by $53$, which of the following measures will change?', NULL, $lyceon_json$[{"key":"A","text":"Median only"},{"key":"B","text":"Mean only"},{"key":"C","text":"Mode only"},{"key":"D","text":"Both median and mode"}]$lyceon_json$::jsonb, 'B', NULL, E'The original data set has $7$ values in ascending order: $13, 17, 19, 22, 22, 25, 31$. The median is the $4$th value, which is $22$. The mode is $22$ since it appears twice. Replacing $31$ with $53$ does not change the $4$th value or the frequency of any repeated value, so the median and mode remain $22$. However, the mean changes because the sum of the values increases by $53 - 31 = 22$. Therefore, only the mean changes. The choice stating median only is incorrect because the middle value is unaffected. The choice stating mode only is incorrect because $22$ still appears exactly twice. The choice stating both median and mode is incorrect for the same reasons.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q6F7Q7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a group of $120$ students, $54$ study chemistry, $39$ study biology, and $13$ study both chemistry and biology. If a student is selected at random from those who study chemistry, what is the probability that the student also studies biology?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{120}$"},{"key":"B","text":"$\\frac{13}{54}$"},{"key":"C","text":"$\\frac{13}{39}$"},{"key":"D","text":"$\\frac{54}{120}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the student studies chemistry, the sample space is the $54$ chemistry students. Of those, $13$ also study biology. Therefore, the probability is $\\frac{13}{54}$. The value $\\frac{13}{120}$ incorrectly uses the total number of students as the denominator instead of the number of chemistry students. The value $\\frac{13}{39}$ incorrectly uses the number of biology students as the denominator. The value $\\frac{54}{120}$ gives the probability of selecting a chemistry student from the entire group, not the conditional probability asked for.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QKYRVK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What is the positive solution of $3x^2 + 11x - 4 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{3}$"},{"key":"B","text":"$\\frac{4}{3}$"},{"key":"C","text":"$4$"},{"key":"D","text":"$\\frac{11}{6}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the quadratic formula, $x = \\frac{-11 \\pm \\sqrt{121 + 48}}{6} = \\frac{-11 \\pm \\sqrt{169}}{6} = \\frac{-11 \\pm 13}{6}$. Taking the positive root gives $x = \\frac{-11 + 13}{6} = \\frac{2}{6} = \\frac{1}{3}$. The value $\\frac{4}{3}$ results from an arithmetic error in simplifying the fraction. The value $4$ is the absolute value of the negative root, obtained by dropping the sign from $x = -4$. The value $\\frac{11}{6}$ comes from using only the $\\frac{-b}{2a}$ portion of the formula without the discriminant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R0RSW8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(1) = 18$ and $f(3) = 162$, what is $f(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$1458$"},{"key":"B","text":"$486$"},{"key":"C","text":"$810$"},{"key":"D","text":"$972$"}]$lyceon_json$::jsonb, 'A', NULL, E'From $f(1) = ab = 18$ and $f(3) = ab^3 = 162$, dividing gives $b^2 = \\frac{162}{18} = 9$, so $b = 3$. Then $a = \\frac{18}{3} = 6$. Therefore $f(5) = 6 \\cdot 3^5 = 6 \\cdot 243 = 1458$. The value $486$ computes $2 \\cdot 243$ by using $a = 2$ from an incorrect setup. The value $810$ results from multiplying $162$ by $5$ instead of continuing the exponential pattern. The value $972$ comes from computing $4 \\cdot 243$ due to an arithmetic error when finding $a$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RYXDQ2', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A chemist mixes a $23\\%$ acid solution with a $71\\%$ acid solution to produce $600$ mL of a $41\\%$ acid solution. How many milliliters of the $23\\%$ solution does the chemist use?', NULL, $lyceon_json$[{"key":"A","text":"$246$"},{"key":"B","text":"$375$"},{"key":"C","text":"$225$"},{"key":"D","text":"$180$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $x$ be the volume of the $23\\%$ solution and $y$ the volume of the $71\\%$ solution. The system is $x + y = 600$ and $0.23x + 0.71y = 0.41(600) = 246$. Substituting $y = 600 - x$ gives $0.23x + 0.71(600 - x) = 246$, which simplifies to $0.23x + 426 - 0.71x = 246$, then $-0.48x = -180$, so $x = 375$. The value $225$ is the volume of the $71\\%$ solution, not the $23\\%$ solution. The value $246$ confuses the total acid content in the final mixture with the volume of one component. The value $180$ is an intermediate result from the equation $-0.48x = -180$ before dividing by the coefficient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SCHNMA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, point $D$ lies on side $\\overline{BC}$ such that $\\overline{AD}$ bisects angle $A$. If angle $B = 43^\\circ$ and angle $C = 71^\\circ$, what is the measure, in degrees, of angle $ADC$?', NULL, $lyceon_json$[{"key":"A","text":"$76^\\circ$"},{"key":"B","text":"$104^\\circ$"},{"key":"C","text":"$109^\\circ$"},{"key":"D","text":"$66^\\circ$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, angle $A = 180^\\circ - 43^\\circ - 71^\\circ = 66^\\circ$. Since $\\overline{AD}$ bisects angle $A$, angle $DAC = \\frac{66^\\circ}{2} = 33^\\circ$. In triangle $ADC$, the angle sum gives angle $ADC = 180^\\circ - 33^\\circ - 71^\\circ = 76^\\circ$. The value $104^\\circ$ is the supplement of $76^\\circ$, arising from confusing the interior angle $ADC$ with the exterior angle at $D$ (equivalently, angle $ADB = 180^\\circ - 76^\\circ = 104^\\circ$). The value $109^\\circ$ results from omitting angle $DAC$ entirely and computing $180^\\circ - 71^\\circ = 109^\\circ$, as though triangle $ADC$ contained only angle $C$ and angle $ADC$. The value $66^\\circ$ is the measure of the full angle $A$, not angle $ADC$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TM8AG1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of $400$ voters in a city found that $52\\%$ support a proposed policy, with a margin of error of $4$ percentage points at a $95\\%$ confidence level. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $52\\%$ of all voters in the city support the policy."},{"key":"B","text":"Between $48\\%$ and $56\\%$ of all voters in the city are likely to support the policy."},{"key":"C","text":"If another sample of $400$ voters is taken, exactly $52\\%$ will support the policy."},{"key":"D","text":"There is a $95\\%$ probability that exactly $52\\%$ of voters support the policy."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of $4$ percentage points means the confidence interval is $52\\% \\pm 4\\%$, or from $48\\%$ to $56\\%$. The interpretation stating that between $48\\%$ and $56\\%$ of all voters are likely to support the policy correctly captures this. The statement that exactly $52\\%$ of all voters support the policy treats a sample statistic as the exact population parameter. The claim that another sample would yield exactly $52\\%$ misunderstands sampling variability. The statement about a $95\\%$ probability that exactly $52\\%$ support the policy confuses the confidence level with a probability statement about a single value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U6PDHX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'The equation $3x - 4y = 20$ represents a line in the $xy$-plane. If the line passes through the point $(k, -2)$, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Substituting $y = -2$ into $3x - 4y = 20$ gives $3x - 4(-2) = 20$, which simplifies to $3x + 8 = 20$. Subtracting $8$ from both sides yields $3x = 12$, so $x = 4$. Therefore $k = 4$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UC63T9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $JKL$, the measure of angle $J$ is $47^\\circ$ and the measure of angle $K$ is $68^\\circ$. What is the measure, in degrees, of angle $L$?', NULL, $lyceon_json$[{"key":"A","text":"$75^\\circ$"},{"key":"B","text":"$115^\\circ$"},{"key":"C","text":"$65^\\circ$"},{"key":"D","text":"$133^\\circ$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. Therefore, angle $L = 180^\\circ - 47^\\circ - 68^\\circ = 65^\\circ$. The value $75^\\circ$ results from an arithmetic error when subtracting $47 + 68 = 115$ from $180$. The value $115^\\circ$ comes from adding $47^\\circ + 68^\\circ$ without subtracting from $180^\\circ$, confusing the sum of two angles with the remaining angle. The value $133^\\circ$ results from subtracting only angle $J$ from $180^\\circ$, giving $180 - 47 = 133$ and ignoring angle $K$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UPK4Q1', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{(3x + 2)^2 - (x - 4)^2}{2x + 6}$ for $x \\neq -3$?', NULL, $lyceon_json$[{"key":"A","text":"$4x - 2$"},{"key":"B","text":"$4x + 2$"},{"key":"C","text":"$4x^2 - 2$"},{"key":"D","text":"$8x - 4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $4x - 2$. Expand the numerator: $(3x + 2)^2 = 9x^2 + 12x + 4$ and $(x - 4)^2 = x^2 - 8x + 16$. Subtracting gives $9x^2 + 12x + 4 - x^2 + 8x - 16 = 8x^2 + 20x - 12$. Factor out $4$: $4(2x^2 + 5x - 3) = 4(2x - 1)(x + 3)$. The denominator $2x + 6 = 2(x + 3)$. Cancel $(x + 3)$ and simplify $\\frac{4}{2} = 2$, yielding $2(2x - 1) = 4x - 2$. The result $4x + 2$ makes a sign error when expanding $(x - 4)^2$, using $+8x$ in the original and then subtracting to get $12x - 8x = 4x$ in the linear term, which cascades into the wrong constant. The result $4x^2 - 2$ retains an $x^2$ term, reflecting a failure to fully factor and cancel the quadratic numerator with the linear denominator. The result $8x - 4$ correctly reaches $4(2x - 1)$ but does not divide by the factor of $2$ from the denominator, expanding as $4(2x - 1) = 8x - 4$ instead of $2(2x - 1) = 4x - 2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V8PCP0', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'What is the vertex of the parabola defined by $h(x) = 2(x + 4)^2 - 7$?', NULL, $lyceon_json$[{"key":"A","text":"$(-4, -7)$"},{"key":"B","text":"$(4, -7)$"},{"key":"C","text":"$(-4, 7)$"},{"key":"D","text":"$(4, 25)$"}]$lyceon_json$::jsonb, 'A', NULL, E'In vertex form $a(x - h)^2 + k$, the vertex is $(h, k)$. Here $h(x) = 2(x - (-4))^2 + (-7)$, so the vertex is $(-4, -7)$. The point $(4, -7)$ uses the wrong sign for the $x$-coordinate, reading the $+4$ in $(x + 4)$ as $h = 4$ instead of recognizing that $(x + 4) = (x - (-4))$ means $h = -4$. The point $(-4, 7)$ reverses the sign of the $y$-coordinate, treating $k$ as $7$ instead of $-7$. The point $(4, 25)$ both misreads the $x$-coordinate as $4$ and drops the $+4$ inside the squared term, computing $2(4)^2 - 7 = 32 - 7 = 25$ instead of the correct $2(4 + 4)^2 - 7 = 2(64) - 7 = 121$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V9M7VM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'A ball is launched upward from a platform. Its height, in feet, after $t$ seconds is modeled by $h(t) = -16t^2 + 48t + 7$. What is the maximum height, in feet, that the ball reaches?', NULL, $lyceon_json$[{"key":"A","text":"$43$"},{"key":"B","text":"$48$"},{"key":"C","text":"$36$"},{"key":"D","text":"$55$"}]$lyceon_json$::jsonb, 'A', NULL, E'The maximum occurs at $t = \\frac{-48}{2(-16)} = \\frac{48}{32} = 1.5$ seconds. Substituting gives $h(1.5) = -16(2.25) + 48(1.5) + 7 = -36 + 72 + 7 = 43$ feet. The value $48$ is the coefficient of $t$, not the maximum height. The value $36$ represents only the gain $-36 + 72$ without adding the initial height of $7$. The value $55$ results from an arithmetic error when combining the terms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VYU2UI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $5$ cm and a height of $12$ cm. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$60\\pi$ cm$^3$"},{"key":"B","text":"$120\\pi$ cm$^3$"},{"key":"C","text":"$150\\pi$ cm$^3$"},{"key":"D","text":"$300\\pi$ cm$^3$"}]$lyceon_json$::jsonb, 'D', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi (5)^2 (12) = \\pi (25)(12) = 300\\pi$ cm$^3$. The value $60\\pi$ results from forgetting to square the radius and computing $\\pi(5)(12) = 60\\pi$. The value $120\\pi$ comes from using the lateral surface area formula $2\\pi rh = 2\\pi(5)(12) = 120\\pi$ instead of the volume formula. The value $150\\pi$ results from a formula setup error: using half the height, $\\pi(5)^2(6) = 150\\pi$, as though the cylinder volume formula included a factor of $\\frac{1}{2}$. The arithmetic $\\pi(25)(6) = 150\\pi$ is itself correct — the mistake is in the formula, not the calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XSIF2M', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A trapezoid has parallel bases of length $11$ cm and $17$ cm, and a height of $6$ cm. What is the area of the trapezoid?', NULL, $lyceon_json$[{"key":"A","text":"$84$ cm$^2$"},{"key":"B","text":"$168$ cm$^2$"},{"key":"C","text":"$51$ cm$^2$"},{"key":"D","text":"$96$ cm$^2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of a trapezoid is $A = \\frac{1}{2}(b_1 + b_2) \\times h = \\frac{1}{2}(11 + 17) \\times 6 = \\frac{1}{2}(28)(6) = 84$ cm$^2$. The value $168$ cm$^2$ comes from omitting the factor of $\\frac{1}{2}$ and computing $(11 + 17) \\times 6 = 168$. The value $51$ cm$^2$ results from using only one base instead of both: $\\frac{1}{2}(17)(6) = 51$. The value $96$ cm$^2$ comes from an arithmetic error in adding the bases ($11 + 17 = 32$ instead of $28$), giving $\\frac{1}{2}(32)(6) = 96$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YV1GSW', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A car rental company charges a flat fee plus a per-mile rate. The total cost $C$, in dollars, for driving $d$ miles is given by the function $C(d) = 0.35d + 52$. What does the value $0.35$ represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The total cost, in dollars, of renting the car for one mile"},{"key":"B","text":"The flat fee, in dollars, charged regardless of how many miles are driven"},{"key":"C","text":"The increase in total cost, in dollars, for each additional mile driven"},{"key":"D","text":"The number of miles included before additional charges apply"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is that $0.35$ represents the increase in total cost, in dollars, for each additional mile driven. In the linear function $C(d) = 0.35d + 52$, the coefficient of $d$ is the rate of change, meaning the cost increases by $\\$0.35$ for every additional mile. The choice describing a flat fee confuses the slope with the $y$-intercept; the flat fee is $\\$52$. The choice about the total cost for one mile incorrectly equates the per-mile rate with the total cost at $d = 1$, which would actually be $C(1) = 52.35$. The choice about miles included misinterprets the slope as a mileage threshold.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20SKC79', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Entomologists at the University of Lisbon hypothesized in 2023 that the rapid spread of the invasive marbled stink bug (Halyomorpha marmorata) across the Iberian Peninsula is facilitated not by wind dispersal, as previously assumed, but by the bugs hitchhiking on commercial freight trucks traveling along major highway corridors. If correct, this would mean that stink bug populations should cluster near truck depots and highway rest stops rather than spreading uniformly across the landscape.', $lyceon_json$[{"key":"A","text":"Stink bug populations are densest within 500 meters of highway rest stops and freight distribution centers across the Iberian Peninsula"},{"key":"B","text":"Marbled stink bugs are physiologically capable of surviving temperatures encountered during long-distance commercial freight transport across Europe"},{"key":"C","text":"The predominant wind patterns across the Iberian Peninsula blow from west to east during the stink bug's primary dispersal season in late summer"},{"key":"D","text":"Several other invasive insect species in southern Europe have been documented spreading primarily through wind-assisted dispersal rather than through human transport networks"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the finding that stink bug populations cluster near highway rest stops and freight distribution centers. The passage explicitly states that the hitchhiking hypothesis predicts clustering near truck depots and rest stops, so this finding would directly confirm that prediction. The finding about bugs surviving freight transport temperatures is relevant but only establishes a precondition for the hypothesis rather than directly supporting it. The finding about west-to-east wind patterns relates to the alternative wind-dispersal explanation, not the truck-hitchhiking hypothesis. The finding about other species spreading via wind dispersal addresses different species and the competing explanation, offering no direct support for the truck-based hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2330M98', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a research study, if accurate, would most effectively support the claim made in the text?', E'Urban ecologist Miriam Feldstein has argued that cities with extensive green roof networks experience measurably lower rates of stormwater runoff than cities of comparable size and rainfall that lack such infrastructure. Feldstein contends that the soil substrate and vegetation on green roofs absorb and retain precipitation that would otherwise flow directly into storm drains, thereby reducing the volume and velocity of water entering municipal drainage systems during heavy rainfall events.', $lyceon_json$[{"key":"A","text":"\"Buildings with green roofs in Stuttgart discharged 61 percent less runoff into storm drains than adjacent conventional rooftops during storms of 30 to 50 millimeters over a 36-month period.\""},{"key":"B","text":"\"Property values within 200 meters of buildings featuring green roofs increased by an average of 7.3 percent between 2018 and 2023, according to municipal assessment data from three mid-sized European cities and two North American metropolitan areas.\""},{"key":"C","text":"\"Green roof installations in Copenhagen reduced ambient rooftop temperatures by an average of 4.2 degrees Celsius during summer months, lowering building cooling costs by approximately 19 percent annually across a sample of 83 commercial buildings.\""},{"key":"D","text":"\"A survey of 14 North American cities found that municipal leaders cited aesthetic improvement, community well-being, and enhanced property appeal as the primary motivations for investing in green roof incentive programs between 2015 and 2022.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the quotation about Stuttgart buildings with green roofs discharging 61 percent less runoff during storms. This directly supports Feldstein''s claim by providing quantitative evidence that green roofs reduce stormwater runoff compared to conventional rooftops. The quotation about property value increases addresses an economic benefit of green roofs unrelated to stormwater management. The quotation about temperature reduction and cooling costs concerns thermal performance, not water retention or runoff reduction. The quotation about municipal leaders'' motivations describes why cities adopt green roofs but provides no data on whether they actually reduce stormwater runoff.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24D9OFJ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Coral reef restoration projects have traditionally relied on fragmenting healthy corals and transplanting pieces onto degraded reefs. However, marine biologist Tariq Osman and his team at the Red Sea Research Institute discovered in 2021 that this approach inadvertently reduces genetic diversity within restored populations. When fragments come from a small number of donor colonies, the resulting reef is genetically homogeneous and therefore more vulnerable to disease outbreaks. Osman''s team proposed an alternative: collecting naturally spawned coral larvae from open water during mass spawning events and settling them onto degraded reef substrates. Early trials showed that larval-settled reefs exhibited 47 percent greater genetic diversity than fragment-transplanted reefs after eighteen months, though fragment-transplanted reefs initially grew faster in terms of surface coverage.', $lyceon_json$[{"key":"A","text":"Fragment transplantation, the standard coral restoration method, limits genetic diversity, and a larval-settlement approach may address this vulnerability despite slower initial growth rates"},{"key":"B","text":"Marine biologist Tariq Osman has demonstrated conclusively that larval settlement is superior to fragment transplantation in all measurable respects when restoring damaged coral reef ecosystems"},{"key":"C","text":"Coral reefs worldwide are declining primarily because restoration projects have failed to maintain adequate genetic diversity among transplanted coral populations over extended periods"},{"key":"D","text":"The Red Sea Research Institute's 2021 study found that fragment-transplanted reefs grow faster than larval-settled reefs, suggesting that speed of coverage should remain the priority in restoration planning"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice identifying fragment transplantation''s genetic diversity limitation and the larval-settlement alternative''s promise despite slower initial growth. The passage presents this balanced comparison as its central point. The choice claiming Osman demonstrated larval settlement is superior ''in all measurable respects'' overstates the findings, since the passage notes fragment-transplanted reefs initially grew faster. The choice about worldwide reef decline being primarily caused by failed restoration projects extrapolates far beyond the passage''s scope. The choice focusing on growth speed as the priority inverts the passage''s emphasis: the text highlights genetic diversity as the more important concern, with growth speed presented as a trade-off rather than the main finding.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24QZ9R3', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Renowned for her intricate sculptures crafted entirely from reclaimed industrial metal, _____ has exhibited her work in seventeen countries, and critics have praised the way her pieces transform discarded machinery into evocative representations of natural forms.', $lyceon_json$[{"key":"A","text":"the work of Hungarian artist Zsófia Kovács"},{"key":"B","text":"Hungarian artist Zsófia Kovács"},{"key":"C","text":"Hungarian artist Zsófia Kovács's latest collection"},{"key":"D","text":"galleries featuring Hungarian artist Zsófia Kovács"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is ''Hungarian artist Zsófia Kovács'' because the opening participial phrase ''Renowned for her intricate sculptures crafted entirely from reclaimed industrial metal'' must modify a person — the one who is renowned and who crafted the sculptures. Only a person can logically be ''renowned for her sculptures'' and then ''has exhibited her work.'' The choice ''the work of Hungarian artist Zsófia Kovács'' creates a dangling modifier because ''work'' cannot be ''renowned for her sculptures,'' and ''the work has exhibited her work'' is nonsensical. The choice ''Hungarian artist Zsófia Kovács''s latest collection'' creates a dangling modifier because a ''collection'' cannot be renowned for sculptures it did not craft, and a collection does not exhibit work in countries. The choice ''galleries featuring Hungarian artist Zsófia Kovács'' creates a dangling modifier because galleries cannot be ''renowned for her intricate sculptures'' — it is the artist, not the galleries, who is renowned for creating the sculptures.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24XOZB3', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts housed in the university''s underground _____ a trove of previously unknown correspondence between two prominent nineteenth-century abolitionists.', $lyceon_json$[{"key":"A","text":"vault contain"},{"key":"B","text":"vault contains"},{"key":"C","text":"vault are containing"},{"key":"D","text":"vault have been containing"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "vault contains" because the subject of the sentence is "collection," which is singular, so it requires the singular verb "contains." The intervening prepositional phrases "of rare manuscripts" and "housed in the university''s underground vault" do not change the number of the subject. The choice "vault contain" uses a plural verb form that does not agree with the singular subject "collection." The choice "vault are containing" uses a plural auxiliary "are" and an unnecessary progressive tense; "collection" is singular and the meaning calls for the simple present, not a progressive form. The choice "vault have been containing" also uses a plural auxiliary "have" that disagrees with the singular subject, and the present perfect progressive tense is inappropriate for a statement of current fact.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25CNPWT', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'When the art historian Celeste Durand examined the brushwork in a previously unattributed seventeenth-century painting, she noticed subtle inconsistencies in the handling of shadow and light that differed from the style of the artist to whom the work was traditionally ascribed. Durand concluded that the painting was likely the product of a workshop assistant who had studied under the master painter but had not fully internalized the master''s technique.', $lyceon_json$[{"key":"A","text":"It presents an observation and then offers an inference drawn from that observation"},{"key":"B","text":"It summarizes a long-standing debate among art historians about workshop attribution practices and then resolves it with newly discovered documentary evidence"},{"key":"C","text":"It describes an experimental technique used by an art historian to authenticate paintings and then evaluates the overall reliability of that technique"},{"key":"D","text":"It introduces a general principle about artistic style in the seventeenth century and then applies it to a specific case study involving an unattributed painting"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the text presents an observation and then offers an inference drawn from that observation. Durand observed inconsistencies in brushwork (observation) and then concluded the painting was likely produced by a workshop assistant (inference). The choice about summarizing a debate is unsupported because the passage describes one historian''s examination, not a debate among multiple scholars, and no documentary evidence is mentioned. The choice about describing an experimental technique and evaluating its reliability mischaracterizes the passage, which recounts a specific analysis rather than evaluating a method''s reliability. The choice about introducing a general principle is incorrect because the passage begins with a specific examination, not a broad stylistic principle.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25GK8ZR', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Lena Okafor has documented the nesting behavior of olive ridley sea turtles along the coast of Odisha, India, for over a decade. Her long-term data show that the turtles consistently return to the same narrow stretch of beach each year. __________ Okafor''s recent tracking study found that individual turtles occasionally bypass their usual nesting site entirely and travel to beaches as far as seventy kilometers away, a behavior she attributes to localized changes in sand temperature.', $lyceon_json$[{"key":"A","text":"For this reason,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"However,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "However," because the sentence before the blank states that turtles consistently return to the same beach, while the sentence after the blank introduces a contrasting finding that some turtles bypass their usual site. This contrast requires a concessive or adversative transition. "For this reason," incorrectly implies the second finding is a consequence of the first, when it is actually a departure from the established pattern. "Similarly," wrongly signals that the two findings are alike, but the second finding contradicts the pattern described in the first. "In other words," incorrectly suggests that the second sentence is a restatement of the first, when it introduces a genuinely different observation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25PX3XQ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The coral restoration initiative, launched by marine ecologist Dara Osei in 2019 to revive degraded reef systems along the _____ employed a technique known as microfragmenting, which involves breaking coral into small pieces that grow up to forty times faster than intact colonies.', $lyceon_json$[{"key":"A","text":"Belizean coast—has"},{"key":"B","text":"Belizean coast; has"},{"key":"C","text":"Belizean coast, has"},{"key":"D","text":"Belizean coast has"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "Belizean coast, has" because the participial phrase "launched by marine ecologist Dara Osei in 2019 to revive degraded reef systems along the Belizean coast" is a nonessential modifier set off from the main clause. Since the phrase was opened with a comma after "initiative," it must be closed with a matching comma before the main verb "has employed." The choice "Belizean coast—has" incorrectly uses a dash to close a phrase that was opened with a comma; parenthetical punctuation must be consistent, so a comma-opened aside cannot be closed with a dash. The choice "Belizean coast; has" incorrectly uses a semicolon, which would separate the subject ("The coral restoration initiative") from its verb ("has employed"), breaking the main clause. The choice "Belizean coast has" omits the closing comma entirely, failing to mark the end of the nonessential phrase and running the modifier directly into the main verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26LEYUP', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to present a contrast between how the suites were regarded before and after Casals''s involvement. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27EY7KR', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In the marshlands of southern Patagonia, a species of burrowing owl known as Athene cunicularia partugoniae has developed an unusual nesting behavior. Unlike most owls, which nest in trees or cliff faces, these owls excavate tunnels up to two meters deep in the soft peat soil. Researchers from the University of Buenos Aires documented in 2019 that these tunnels maintain a remarkably stable internal temperature of 14 degrees Celsius regardless of external conditions, which range from minus 8 to 35 degrees Celsius seasonally. The tunnels thus function as natural climate-control systems for the owls and their offspring.', $lyceon_json$[{"key":"A","text":"A species of burrowing owl in Patagonia digs tunnels that provide consistent thermal conditions for nesting despite extreme seasonal temperature variation"},{"key":"B","text":"Researchers at the University of Buenos Aires spent years cataloguing owl species across southern Patagonia and comparing their nesting strategies to those found elsewhere"},{"key":"C","text":"Burrowing owls are the only owl species that nest underground, making them uniquely adapted to the harsh climate of Patagonia"},{"key":"D","text":"The peat soil of southern Patagonia has distinctive insulating properties that many animal species, including owls, exploit for temperature regulation in their habitats"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that a Patagonian burrowing owl digs tunnels providing consistent thermal conditions despite seasonal extremes. The passage focuses on this owl''s unusual tunnel-nesting behavior and the stable temperature the tunnels maintain. The choice about researchers cataloguing owl species misrepresents the passage, which describes a single species'' behavior rather than a comparative survey. The choice claiming burrowing owls are the only underground-nesting species overstates the text, which says they differ from ''most owls'' but does not claim uniqueness. The choice about peat soil''s properties being exploited by many species broadens the passage''s scope beyond what it states, since only one species is discussed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27XMGKI', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would Saldana most likely respond to Lindgren''s argument?', E'Text 1: Ecologist Marta Lindgren has argued that reintroducing wolves to regions where they were historically present leads to a cascade of ecological benefits, including reduced deer overpopulation, regrowth of riparian vegetation, and stabilization of riverbank erosion.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EP21V6', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Industrial designer Kenji Watanabe spent three years developing a bicycle helmet made entirely from mycelium, the root-like network of fungi. Traditional polystyrene helmets take an estimated 500 years to decompose in landfills, whereas Watanabe''s mycelium helmet biodegrades within 90 days when composted. Independent impact testing conducted in 2023 confirmed that the mycelium helmet meets all current European safety certification standards for cycling helmets. Given these results, Watanabe''s innovation suggests that ________', $lyceon_json$[{"key":"A","text":"sustainable materials can satisfy rigorous safety requirements while also addressing the environmental costs associated with conventional helmet disposal"},{"key":"B","text":"polystyrene will no longer be used in any consumer safety equipment once mycelium-based alternatives become commercially available worldwide"},{"key":"C","text":"the European safety certification standards for cycling helmets should be revised to incorporate specific environmental sustainability criteria for materials used in manufacturing"},{"key":"D","text":"mycelium-based materials are inherently stronger than polystyrene under all impact conditions and should replace synthetic polymers in every protective equipment application"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that sustainable materials can meet safety requirements while addressing environmental disposal costs. The passage establishes both that the mycelium helmet biodegrades rapidly and that it passes safety testing, so inferring that sustainability and safety can coexist is directly supported. The choice predicting polystyrene will no longer be used in any safety equipment extends far beyond the passage, which describes one prototype without addressing industry-wide adoption. The choice about revising certification standards to include sustainability criteria introduces a policy recommendation unsupported by the text. The choice claiming mycelium is inherently stronger than polystyrene in all conditions overstates the evidence; the passage confirms the helmet meets standards, not that mycelium outperforms polystyrene universally.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FGM5FX', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'The critic''s review of the gallery exhibition was notably ______, acknowledging the technical proficiency of the artists while simultaneously arguing that the collection lacked thematic coherence and failed to provoke any meaningful emotional response in the viewer.', $lyceon_json$[{"key":"A","text":"perfunctory"},{"key":"B","text":"ambivalent"},{"key":"C","text":"laudatory"},{"key":"D","text":"dismissive"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "ambivalent." The passage describes a review that contains both positive assessment (acknowledging technical proficiency) and negative judgment (lacking coherence, failing to provoke emotion). "Ambivalent" means having mixed or contradictory feelings, which precisely captures this dual evaluation. "Perfunctory" means carried out with minimal effort or superficial attention, but the review as described engages deeply with both the strengths and weaknesses of the exhibition, so calling it perfunctory would be incoherent. "Laudatory" means expressing praise, but the review explicitly criticizes the collection for lacking coherence and emotional impact, so it cannot be characterized as purely praising. "Dismissive" means treating something as unworthy of consideration, but the review acknowledges genuine technical skill, which is incompatible with a dismissive stance.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HB0X43', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologists studying coral reef ecosystems have observed that certain species of parrotfish play a ______ role in maintaining reef health, as without their constant grazing on algae, coral structures would be rapidly overtaken and smothered.', $lyceon_json$[{"key":"A","text":"token"},{"key":"B","text":"vital"},{"key":"C","text":"redundant"},{"key":"D","text":"ceremonial"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "vital." The passage describes parrotfish as essential to reef health because without their grazing, coral would be overtaken by algae. "Vital" means critically important or indispensable, which matches this description. "Token" means symbolic or minimal, implying the role is insignificant, which contradicts the passage''s emphasis on the fish being necessary. "Redundant" means unnecessary or superfluous, which is the opposite of what the passage conveys. "Ceremonial" relates to formal rituals and has no coherent connection to an ecological function.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HP1YKT', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the conclusion drawn by Vasquez and her colleagues?', E'Neuropsychologist Elena Vasquez and her colleagues at the University of Guadalajara published a 2022 study concluding that bilingual individuals who regularly switch between languages in daily conversation exhibit stronger cognitive flexibility than monolinguals of the same age and education level. Their study measured cognitive flexibility using a task-switching paradigm in which participants alternated between categorizing images by color and by shape. Bilingual participants who reported frequent code-switching scored 23 percent higher on task-switching accuracy than monolingual controls, leading Vasquez to conclude that the habitual practice of managing two active languages enhances domain-general cognitive flexibility.', $lyceon_json$[{"key":"A","text":"Bilingual participants in a follow-up study who rarely code-switched performed equally well on the task-switching assessment as frequent code-switchers, matching monolingual control scores"},{"key":"B","text":"Monolingual participants who practiced the specific task-switching paradigm used in Vasquez's study for two weeks showed modest improvement on that particular test without any language training whatsoever"},{"key":"C","text":"A meta-analysis of 39 studies found that bilingual advantages in executive function tasks are most pronounced among adults over the age of sixty and less consistently observed among younger adults in varied populations"},{"key":"D","text":"Vasquez's study used a participant pool drawn exclusively from university students, limiting the generalizability of its findings to populations with different educational backgrounds, socioeconomic characteristics, and geographic regions"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the finding that bilinguals who rarely code-switch performed equally well as frequent code-switchers and matched monolinguals. Vasquez''s conclusion specifically links habitual code-switching to enhanced cognitive flexibility; if bilinguals who do not code-switch perform just as well, the causal link between code-switching practice and cognitive flexibility is directly undermined. The finding about monolinguals improving through practice addresses test familiarity effects but does not challenge whether code-switching itself drives better performance in bilinguals. The meta-analysis finding about age-related variation concerns the scope of bilingual advantages generally, not the specific mechanism Vasquez identified. The finding about the university-only participant pool raises a methodological limitation about generalizability but does not contradict the core conclusion about the relationship between code-switching and cognitive flexibility.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JFB2TT', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes how Dragovic''s position in Text 2 differs from Khoury''s position in Text 1?', E'Text 1: Literary scholar Amira Khoury contends that the epistolary novels of the eighteenth century functioned primarily as vehicles for moral instruction, with authors constructing letter exchanges to model virtuous behavior and guide readers toward socially sanctioned norms of conduct.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K4JH8Z', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Fatima Benali, studying clay tablets excavated from a 3,200-year-old trading post in coastal Morocco, identified inscriptions in three distinct scripts: one local Amazigh syllabary, one early Phoenician alphabet, and one previously undocumented symbol system. Benali noted that the undocumented symbols appeared exclusively on tablets recording transactions involving a specific purple dye extracted from local sea snails. No other commodity at the trading post was recorded using these symbols. Benali hypothesized that the undocumented script was ________', $lyceon_json$[{"key":"A","text":"a specialized notation system developed specifically for the purple dye trade, possibly to restrict knowledge of the commodity's sourcing and pricing to a select group of traders"},{"key":"B","text":"an earlier version of the Phoenician alphabet that evolved into the standard form found on other tablets at the same site through gradual simplification over several centuries"},{"key":"C","text":"a decorative artistic convention applied to tablets as ornamentation, bearing no linguistic or transactional meaning whatsoever despite appearing alongside genuine trade records"},{"key":"D","text":"evidence that the trading post conducted commerce with a civilization more technologically advanced than either the local Amazigh population or the Phoenician traders who visited the coast"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice proposing a specialized notation for the purple dye trade. The passage notes that the undocumented symbols appeared exclusively on tablets recording purple dye transactions and no other commodity, which supports the hypothesis that the script served that specific trade. Because Benali framed this as a hypothesis rather than a certainty, the inference remains tentative, consistent with the passage''s hedging language. The choice describing an earlier Phoenician alphabet version is not well supported because the passage characterizes the symbols as a separate, ''previously undocumented symbol system'' distinct from the Phoenician alphabet already present at the site, making an evolutionary relationship unlikely given the evidence presented. The choice calling the symbols purely decorative is inconsistent with the passage''s explicit link between the symbols and specific trade records, which implies functional transactional meaning. The choice about a more technologically advanced civilization introduces a claim about technological superiority that nothing in the passage supports; a unique script does not imply greater technological advancement.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KC0WEP', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to emphasize the nutritional value of baobab fruit. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L5HQPM', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Although the novelist''s early works were celebrated for their exuberant prose and sweeping narratives, critics noted that her later fiction was markedly ______, favoring restrained language and intimate, narrowly focused character studies.', $lyceon_json$[{"key":"A","text":"peripheral"},{"key":"B","text":"flamboyant"},{"key":"C","text":"subdued"},{"key":"D","text":"obsolete"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is "subdued." The passage contrasts the novelist''s early exuberant prose with her later work, which uses restrained language and narrow focus. "Subdued" means quiet, restrained, or toned down, which directly matches this contrast. "Peripheral" means marginal or on the outer edge of something, which describes relevance or position rather than tone or style, making it incoherent in this context. "Flamboyant" means showy and extravagant, which describes the early works rather than the later ones and contradicts the contrast the passage establishes. "Obsolete" means no longer in use or outdated, which would imply the fiction is old-fashioned rather than restrained in style, a meaning unsupported by the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MIYGJS', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Architectural historian Tomasz Kowalski argues that the widespread adoption of reinforced concrete in early twentieth-century Warsaw allowed architects to experiment with building forms that masonry construction could not support. Many of these concrete structures, Kowalski notes, featured cantilevered balconies and open floor plans that became hallmarks of the city''s interwar modernist style. __________ Kowalski cautions that this structural freedom came at a cost: the iron reinforcements used in that era were prone to corrosion, and dozens of these buildings now require expensive stabilization work to prevent collapse.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"To illustrate this point,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "Nevertheless," because the sentences before the blank praise the structural freedom that reinforced concrete enabled, while the sentence after the blank introduces a drawback — the corrosion of iron reinforcements and the resulting need for costly repairs. This shift from a positive assessment to a cautionary qualification requires a concessive transition. "Specifically," would indicate that the following sentence provides a detailed example of the preceding point, but the sentence after the blank introduces a negative consequence rather than elaborating on an advantage. "Consequently," implies a direct cause-and-effect relationship, but corrosion is not a logical consequence of architectural experimentation — it is a separate material limitation. "To illustrate this point," suggests the following sentence exemplifies the preceding claim about structural freedom, when it actually qualifies and complicates that claim by raising a concern about durability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MSLY6G', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Elara Okonkwo has spent over a decade studying deep-sea bioluminescence in the Mariana Trench. Her research has revealed that certain species of anglerfish produce light through a symbiotic relationship with _____ finding has prompted new investigations into microbial partnerships at extreme ocean depths.', $lyceon_json$[{"key":"A","text":"bacteria, this"},{"key":"B","text":"bacteria. This"},{"key":"C","text":"bacteria, furthermore, this"},{"key":"D","text":"bacteria this"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "bacteria. This" because the clause before the blank ("Her research has revealed that certain species of anglerfish produce light through a symbiotic relationship with bacteria") and the clause after it ("this finding has prompted new investigations") are both independent clauses. A period properly separates them into two sentences. The choice "bacteria, this" creates a comma splice by joining two independent clauses with only a comma. The choice "bacteria, furthermore, this" also creates a comma splice; "furthermore" is a conjunctive adverb and cannot join independent clauses with commas alone—a semicolon before it would be required. The choice "bacteria this" produces a run-on sentence by omitting all punctuation between the two independent clauses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N8YEEN', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economist Renata Oliveira analyzed wage data from 1,400 Brazilian municipalities between 2010 and 2020 and found that regions experiencing rapid expansion of soybean monoculture saw average agricultural wages rise by 31 percent during the period. However, Oliveira also noted that in those same regions, employment in subsistence farming declined by 54 percent, and the number of independent smallholders fell by 39 percent. Meanwhile, the cost of staple foods purchased locally in those regions rose by 28 percent as land previously used for diverse food crops was converted to soybean production. Taken together, Oliveira''s findings suggest that the wage gains from monoculture expansion ________', $lyceon_json$[{"key":"A","text":"may overstate the actual improvement in economic well-being for rural populations, since rising local food costs and the displacement of smallholders offset much of the income increase that aggregate wage statistics capture"},{"key":"B","text":"demonstrate that soybean monoculture is economically harmful in every measurable dimension and should be immediately curtailed through federal agricultural policy interventions across all Brazilian municipalities"},{"key":"C","text":"are entirely attributable to inflation in the Brazilian economy during the 2010-to-2020 period rather than to any genuine increase in the purchasing power of agricultural workers in soybean-producing regions"},{"key":"D","text":"prove that subsistence farming is more economically productive per hectare than soybean monoculture when all environmental and social externalities are included in a comprehensive cost-benefit accounting framework"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that wage gains may overstate actual improvement because rising food costs and smallholder displacement offset the income increase. The passage presents countervailing data: wages rose, but food costs increased and independent farming declined, supporting the inference that aggregate wage statistics paint an incomplete picture. The choice calling soybean monoculture harmful in every dimension and demanding immediate curtailment goes far beyond the passage, which presents a nuanced picture including genuine wage gains. The choice attributing wage gains entirely to inflation introduces a factor the passage never mentions and dismisses the wage increase as illusory without textual support. The choice claiming subsistence farming is more productive per hectare requires a comprehensive analysis the passage does not provide; the passage presents correlations without comparing per-hectare productivity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RL66KC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the research team first analyzed the soil samples from the excavation site, they discovered unusually high concentrations of phosphorus. Further _____ that the elevated levels resulted from centuries of agricultural activity rather than from natural geological processes.', $lyceon_json$[{"key":"A","text":"testing confirms"},{"key":"B","text":"testing will confirm"},{"key":"C","text":"testing confirmed"},{"key":"D","text":"testing has been confirming"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is ''testing confirmed'' because the passage describes a completed sequence of past events: the team analyzed samples, discovered elevated phosphorus, and then conducted further testing that established the cause. Since all of these actions occurred in the past and have been completed, the simple past tense ''confirmed'' is the appropriate form. The choice ''testing confirms'' shifts to the present tense, which would suit an ongoing or general truth but not a completed investigation that the passage presents as finished. The choice ''testing will confirm'' uses the future tense, implying the testing has not yet occurred, which conflicts with a passage recounting events that have already taken place. The choice ''testing has been confirming'' uses the present perfect progressive, implying an action still in progress, but the passage presents the further testing as a completed event yielding a definitive finding, not an ongoing process.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ROQ11E', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the text?', E'The Venus flytrap, native to a small region of the Carolinas, captures insects using a pair of hinged lobes at the end of each leaf. When trigger hairs on the inner surface of the lobes are stimulated, the lobes snap shut in less than a tenth of a second, trapping the prey inside.', $lyceon_json$[{"key":"A","text":"To argue that the Venus flytrap is the most efficient predatory plant found in the southeastern United States"},{"key":"B","text":"To describe a mechanism by which a plant species captures prey"},{"key":"C","text":"To compare the hunting strategies of several carnivorous plant species native to the Carolinas"},{"key":"D","text":"To explain why certain insects are attracted to the surface of the Venus flytrap's leaves"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the choice stating that the text describes a mechanism by which a plant species captures prey. The passage explains how the Venus flytrap''s hinged lobes and trigger hairs function to trap insects, which is a description of a biological capture mechanism. The choice claiming the text argues the Venus flytrap is the most efficient predatory plant overstates the passage, which makes no comparative claim about efficiency. The choice about comparing hunting strategies of several species is contradicted by the passage, which discusses only the Venus flytrap. The choice about explaining why insects are attracted to the leaves misidentifies the purpose; the passage describes how the trap works, not what draws insects to it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SC3QXU', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the overall structure of the text?', E'Conventional accounts hold that the decline of the Roman Empire''s western provinces resulted primarily from external military pressure exerted by migrating Germanic peoples. However, recent archaeological findings in the Danube frontier region complicate this narrative: many settlements show evidence of gradual cultural integration rather than violent displacement, with Roman and Germanic material culture coexisting in the same habitation layers for several generations before any discernible administrative collapse occurred.', $lyceon_json$[{"key":"A","text":"It introduces archaeological evidence that challenges a historical explanation presented in the first sentence"},{"key":"B","text":"It provides additional examples that reinforce and further substantiate the conventional theory of decline described in the first sentence"},{"key":"C","text":"It shifts the discussion from the political causes of the empire's decline to an analysis of the lasting cultural achievements of Roman civilization in the frontier region"},{"key":"D","text":"It proposes an alternative chronology for the fall of the western provinces by arguing that administrative collapse preceded the period of cultural change in the frontier settlements"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the second sentence introduces archaeological evidence that challenges a historical explanation. The word ''complicate'' signals that the new findings qualify rather than simply support the conventional account: evidence of gradual cultural integration suggests the decline involved more than external military pressure alone, without ruling out military factors entirely. The choice claiming the examples reinforce the conventional theory reverses the relationship signaled by ''However'' and ''complicate this narrative.'' The choice about shifting to an analysis of lasting cultural achievements misidentifies the purpose; the evidence of coexisting material culture is cited to qualify the decline narrative, not to celebrate Roman cultural accomplishments. The choice proposing an alternative chronology with administrative collapse preceding cultural change inverts the temporal sequence described in the passage, which states that cultural coexistence preceded administrative collapse.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T2DUUH', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the overall structure and central claim of the text?', E'Historians have long attributed the decline of the Khmer Empire in the fifteenth century to military pressure from the Ayutthaya kingdom. Yet hydraulic engineer Priya Chandrasekaran, analyzing sediment cores from the Tonle Sap basin in 2022, found evidence that the empire''s elaborate water management network experienced cascading failures beginning around 1380 CE, well before Ayutthaya''s major campaigns. Chandrasekaran argues that prolonged drought destabilized the canal system, reducing agricultural output and weakening the empire''s economic base. This interpretation does not dismiss military factors entirely; rather, it repositions them as consequences of an already-fragile state. Some scholars, however, counter that sediment records cannot reliably distinguish drought-induced canal failure from deliberate canal abandonment during political reorganization, cautioning against over-reliance on environmental data alone.', $lyceon_json$[{"key":"A","text":"It presents a traditional explanation, introduces an alternative hypothesis based on new environmental evidence, and then acknowledges a methodological objection to that hypothesis raised by other scholars"},{"key":"B","text":"It contrasts two competing military explanations for the Khmer Empire's decline before ultimately arguing that environmental degradation was the sole cause of the empire's collapse"},{"key":"C","text":"It describes a scholarly consensus about the Khmer Empire's decline and then summarizes how Chandrasekaran's sediment analysis confirmed that consensus through quantitative hydraulic modeling"},{"key":"D","text":"It presents Chandrasekaran's environmental hypothesis as definitively overturning the military explanation, then briefly mentions other scholars who support a slightly modified version of her interpretation"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing the text as presenting a traditional explanation, introducing an alternative hypothesis from environmental evidence, and acknowledging a methodological objection. This accurately traces the passage''s three-part structure: the military explanation, Chandrasekaran''s drought hypothesis, and scholars'' counterargument about sediment data reliability. The choice about two competing military explanations misreads the passage, which contrasts a military explanation with an environmental one, not two military accounts, and the passage does not claim environmental degradation was the sole cause. The choice describing a scholarly consensus being confirmed misrepresents the passage, since Chandrasekaran challenges rather than confirms the traditional view. The choice stating Chandrasekaran definitively overturned the military explanation distorts the passage''s nuanced framing, which explicitly says she ''does not dismiss military factors entirely,'' and the other scholars raise objections rather than supporting her.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VNWO3G', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how does Hedlund''s finding relate to Obasi''s research?', E'Text 1: Psychologist Renata Obasi''s research suggests that bilingual individuals frequently exhibit enhanced cognitive flexibility compared to monolinguals, particularly in tasks requiring the suppression of irrelevant information and rapid switching between rule sets.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WG25FL', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Gothenburg recently analyzed sediment cores from three lakes in central Sweden to reconstruct precipitation patterns over the past nine centuries. Their findings revealed that the region experienced prolonged droughts during the fourteenth and fifteenth centuries. __________ the team noted that these dry spells coincided with periods of significant agricultural decline documented in local parish records.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Alternatively,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "Furthermore," because the sentence after the blank adds a supporting detail about agricultural decline that reinforces the finding about prolonged droughts. Both sentences point in the same direction, so an additive transition is needed. "In contrast," incorrectly signals opposition between two ideas that are actually complementary. "Alternatively," wrongly implies a different possibility or option rather than an additional finding. "On the other hand," similarly introduces a contrasting perspective, which does not fit the relationship between the two pieces of information presented.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WH4570', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to support the claim that Bo Bardi''s MASP design reflected a philosophy of architecture as public service. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X7FX2Z', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'During a recent expedition in northern Peru, archaeologist Tomás Guerrero unearthed pottery fragments bearing symbols previously unknown to _____ symbols, which resemble neither Incan nor Moche iconography, may represent an undocumented numerical system used by a pre-ceramic coastal society.', $lyceon_json$[{"key":"A","text":"researchers, the"},{"key":"B","text":"researchers the"},{"key":"C","text":"researchers; the"},{"key":"D","text":"researchers, however, the"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "researchers; the" because both the clause before the blank and the clause after it are independent clauses, and a semicolon properly joins two closely related independent clauses. The choice "researchers, the" creates a comma splice—two independent clauses joined by only a comma. The choice "researchers the" produces a run-on sentence with no punctuation at all between the clauses. The choice "researchers, however, the" is also a comma splice; "however" is a conjunctive adverb, and using commas alone on both sides of it cannot correctly join two independent clauses. A semicolon before "however" would be required for that construction to be grammatically correct.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
